17	        graph = new int[teamNumber][teamNumber];
18	        for(int i = 0; i < teamNumber; i ++) {
19	            graph[i] = new int[teamNumber];
20	        }
21	        //随机生成比赛结果的有向图的邻接矩阵
22	        for(int i = 0; i < teamNumber; i ++) {
23	            graph[i][i] = 0;
24	            for(int j = i + 1; j < teamNumber; j ++) {
25	                int temp = (int)(Math.random() * 10) + 1;
26	                if(temp <= 5){
27	                    graph[i][j] = 0;
28	                    graph[j][i] = 1;
29	                }else{
