92	    static class Stack{
93	        private List<Node> nodeList = new ArrayList<>();
94	    
95	        public void push(Node node) {
96	            nodeList.add(node);
97	        }
98	    
99	        public Node pop() {
100	            Node node = getTop();
101	            nodeList.remove(nodeList.size() - 1);
102	            return node;
103	        }
104	    
105	        public Node getTop() {
106	            return nodeList.get(nodeList.size() - 1);
