113	                builder.append(" --> " + nodeList.get(i).getIndex());
114	            }
115	            builder.append(" ]");
116	            return builder.toString();
117	        }
118	
119	        public Boolean isFull() {
120	            if(nodeList.size() == teamNumber) {
121	                return true;
122	            } else {
123	                return false;
124	            }
125	        }
126	
127	        public Boolean isEmpty() {
128	            if(nodeList.size() == 0) {
129	                return true;
130	            } else {
131	                return false;
132	            }
