//按照项目读入前三名或前五名
private static void inputScore() {
    System.out.print("请输入要录入成绩的项目编号：");
    int projectLabel = scanner.nextInt();
    if(projectLabel < 1 || projectLabel > projectNumber) {
        System.out.println("项目编号有误！");
        return;
    }
    Project project = projectList.get(projectLabel - 1);
    //取前三名的积分为5、3、2，取前五名的积分为7、5、3、2、1
    int[] scores = project.getIsThreeProject() ? new int[]{5, 3, 2} : new int[]{7, 5, 3, 2, 1};
    //建立学院编号到学院的映射，方便按照编号录入
    Map<Integer, School> schoolMap = new HashMap<Integer, School>();
    for(School school : schoolList) {
        schoolMap.put(school.getSchoolLabel(), school);
    }
    //该项目若已录入过成绩，先撤销原有的积分
    ArrayList<School> winnerSchools = project.getWinnerSchools();
    for(int i = 0; i < winnerSchools.size(); i ++) {
        School school = winnerSchools.get(i);
        school.addTotalScore(-scores[i]);
        if(project.getIsMaleProject()) {
            school.addMaleScore(-scores[i]);
        } else {
            school.addFemaleScore(-scores[i]);
        }
    }
    project.clearWinnerSchools();
    //按照名次依次录入获得名次的学院并累加积分
    for(int i = 0; i < scores.length; i ++) {
        System.out.print("请输入第" + (i + 1) + "名的学院编号：");
        School school = schoolMap.get(scanner.nextInt());
        while(school == null || winnerSchools.contains(school)) {
            System.out.print("学院编号有误或该学院已获得名次，请重新输入：");
            school = schoolMap.get(scanner.nextInt());
        }
        project.addWinnerSchools(school);
        school.addTotalScore(scores[i]);
        if(project.getIsMaleProject()) {
            school.addMaleScore(scores[i]);
        } else {
            school.addFemaleScore(scores[i]);
        }
    }
    System.out.println("项目" + projectLabel + "的成绩录入完成！");
}
