private static void searchBySchool() {
    System.out.print("请输入要查询的学院编号：");
    int schoolLabel = scanner.nextInt();
    School targetSchool = null;
    for(School school : schoolList) {
        if(school.getSchoolLabel() == schoolLabel) {
            targetSchool = school;
            break;
        }
    }
    if(targetSchool == null) {
        System.out.println("查无此学院！");
        return;
    }
    System.out.println("学院" + schoolLabel + "的总分为" + targetSchool.getTotalScore()
        + "，男子团体总分为" + targetSchool.getMaleScore() + "，女子团体总分为" + targetSchool.getFemaleScore());
    System.out.println("该学院取得名次的项目如下：");
    boolean hasWinned = false;
    for(Project project : projectList) {
        int rank = project.getWinnerSchools().indexOf(targetSchool);
        if(rank == -1) {
            continue;
        }
        int[] scores = project.getIsThreeProject() ? new int[]{5, 3, 2} : new int[]{7, 5, 3, 2, 1};
        System.out.println((project.getIsMaleProject() ? "男子" : "女子") + "项目" + project.getProjectLabel()
            + "：第" + (rank + 1) + "名，得分" + scores[rank]);
        hasWinned = true;
    }
    if(!hasWinned) {
        System.out.println("该学院未在任何项目中取得名次！");
    }
}
